// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 plays) public {
        vm.assume(plays > 0 && plays <= 10);
        for (uint256 i = 0; i < plays; i++) {
            address player = address(uint160(i + 1));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
        }
        assertTrue(c.pot() % 10 == 0);
    }
}
